import { KIND_LABEL } from "../domain/reminder";
import { maskDevice } from "../push/deviceToken";
import { DeliveredPush, PushqClient } from "../push/pushqClient";
import { ReminderRepository } from "../repository/reminderRepository";
import { compare, LocalDate, LocalDateTime } from "../time/localTime";

export type LineStatus = "발송" | "미발송" | "예약";

export interface ReportLine {
  key: string;
  memberId: string;
  kind: string;
  dueAt: LocalDateTime;
  sendAt: LocalDateTime;
  ticket: string;
  device: string;
  status: LineStatus;
  deliveredAt?: LocalDateTime;
}

export interface ReminderReport {
  date: LocalDate;
  asOf: LocalDateTime | null;
  planned: number;
  delivered: number;
  missing: number;
  pending: number;
  lines: ReportLine[];
  text: string;
}

/** 출금일 기준 알림 발송 현황 — 운영 화면용 */
export class ReminderReportBuilder {
  constructor(private readonly reminders: ReminderRepository, private readonly push: PushqClient) {}

  build(date: LocalDate, asOf: LocalDateTime | undefined): ReminderReport {
    const byTag = new Map<string, DeliveredPush>();
    for (const d of this.push.delivered()) if (!byTag.has(d.tag)) byTag.set(d.tag, d);

    const lines: ReportLine[] = this.reminders.byPlanDate(date).map((r) => {
      const hit = byTag.get(r.key);
      let status: LineStatus;
      if (hit) status = "발송";
      else if (asOf && compare(r.sendAt, asOf) <= 0) status = "미발송";
      else status = "예약";
      return {
        key: r.key,
        memberId: r.memberId,
        kind: KIND_LABEL[r.kind],
        dueAt: r.dueAt,
        sendAt: r.sendAt,
        ticket: r.ticket ?? "-",
        device: maskDevice(r.device),
        status,
        deliveredAt: hit?.at,
      };
    });
    const count = (s: LineStatus) => lines.filter((l) => l.status === s).length;
    const planned = lines.length;
    const delivered = count("발송");
    const missing = count("미발송");
    const pending = count("예약");
    return {
      date,
      asOf: asOf ?? null,
      planned,
      delivered,
      missing,
      pending,
      lines,
      text: `${date} 알림 — 예약 ${planned} / 발송 ${delivered} / 미발송 ${missing} / 대기 ${pending}`,
    };
  }
}
---DOMAIN
import { LocalDate, LocalDateTime } from "../time/localTime";

export type ReminderKind = "BILL_DUE" | "RETRY";

export const KIND_LABEL: Record<ReminderKind, string> = {
  BILL_DUE: "출금 예정",
  RETRY: "재출금 안내",
};

const KIND_CODE: Record<ReminderKind, string> = {
  BILL_DUE: "due",
  RETRY: "retry",
};

export interface Reminder {
  /** 푸시 태그로도 쓰는 업무 키 — 같은 알림은 늘 같은 키 */
  key: string;
  kind: ReminderKind;
  memberId: string;
  autopayId: string;
  device: string;
  /** 이 알림이 안내하는 출금(또는 재출금) 시각 */
  dueAt: LocalDateTime;
  /** 실제 발송 예약 시각 */
  sendAt: LocalDateTime;
  /** 리포트 묶음 기준일(= 출금일) */
  planDate: LocalDate;
  message: string;
  ticket?: string;
}

export function reminderKey(kind: ReminderKind, autopayId: string, dueAt: LocalDateTime): string {
  return `rmd.${autopayId}.${KIND_CODE[kind]}.${dueAt.slice(0, 10).replace(/-/g, "")}`;
}
---APP
import { mountAccountRoutes, mountReminderRoutes } from "./api/routes";
import { Response, Router } from "./api/router";
import { AppConfig, loadConfig } from "./config";
import { PushqClient } from "./push/pushqClient";
import { ReminderReportBuilder } from "./report/reminderReport";
import { AutopayRepository } from "./repository/autopayRepository";
import { MemberRepository } from "./repository/memberRepository";
import { ReminderRepository } from "./repository/reminderRepository";
import { QuietHours } from "./scheduling/quietHours";
import { SendTimePolicy } from "./scheduling/sendTime";
import { ReminderPlanner } from "./service/reminderPlanner";
import { ReminderService } from "./service/reminderService";

export interface App {
  config: AppConfig;
  handle(method: string, url: string, body?: unknown): Response;
}

export function createApp(overrides: Partial<AppConfig> = {}): App {
  const config = loadConfig(overrides);
  const members = new MemberRepository();
  const autopays = new AutopayRepository();
  const reminders = new ReminderRepository();
  const push = new PushqClient(config.pushqBin, config.pushqHome);
  const policy = new SendTimePolicy(new QuietHours(config.quietStart, config.quietEnd, config.quietFallback));
  const planner = new ReminderPlanner(members, autopays, policy, config.retryNoticeLeadMinutes);
  const service = new ReminderService(planner, autopays, reminders, push, config.retryDelayMinutes);
  const report = new ReminderReportBuilder(reminders, push);

  const router = new Router();
  mountAccountRoutes(router, config, members, autopays);
  mountReminderRoutes(router, service, report, members, push);
  return { config, handle: (m, u, b) => router.handle(m, u, b) };
}

